using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize] public class CustomersController(ApplicationDbContext db,AuditService audit):Controller{
 public async Task<IActionResult> Index(string? q){var x=db.Customers.Include(c=>c.Owner).AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))x=x.Where(c=>c.OwnerId==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value);if(!string.IsNullOrWhiteSpace(q))x=x.Where(c=>c.Name.Contains(q)|| (c.Email??"").Contains(q));ViewBag.Query=q;return View(await x.OrderByDescending(c=>c.CreatedAt).ToListAsync());}
 [HttpGet]public IActionResult Create()=>View(new Customer());
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(Customer m){if(!ModelState.IsValid)return View(m);m.OwnerId=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value;m.CreatedAt=DateTime.UtcNow;db.Customers.Add(m);await db.SaveChangesAsync();await audit.WriteAsync(User,"Customers","Create",m.Id.ToString(),m.Name);TempData["Success"]="Customer created.";return RedirectToAction(nameof(Index));}
 [HttpGet]public async Task<IActionResult>Edit(int id){var m=await db.Customers.FindAsync(id);if(m==null)return NotFound();if(!CanAccess(m.OwnerId))return Forbid();return View(m);}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(int id,Customer m){if(id!=m.Id)return BadRequest();var old=await db.Customers.FindAsync(id);if(old==null)return NotFound();if(!CanAccess(old.OwnerId))return Forbid();if(!ModelState.IsValid)return View(m);old.Name=m.Name;old.Email=m.Email;old.Phone=m.Phone;old.Address=m.Address;old.Status=m.Status;old.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.WriteAsync(User,"Customers","Update",id.ToString(),old.Name);TempData["Success"]="Customer updated.";return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Delete(int id){var m=await db.Customers.FindAsync(id);if(m==null)return NotFound();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))return Forbid();db.Customers.Remove(m);await db.SaveChangesAsync();await audit.WriteAsync(User,"Customers","Delete",id.ToString(),m.Name);return RedirectToAction(nameof(Index));}
 bool CanAccess(string? owner)=>User.IsInRole("Admin")||User.IsInRole("Manager")||owner==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
}
